from copy import deepcopy


def update_library(categories, books, operations):
    if not isinstance(categories, dict) or not isinstance(books, dict) or not isinstance(operations, list):
        raise ValueError("invalid input")

    def valid_id(value):
        return isinstance(value, int) and not isinstance(value, bool) and value > 0

    cats = deepcopy(categories)
    items = deepcopy(books)
    if any(not valid_id(k) or not isinstance(v, str) or not v for k, v in cats.items()):
        raise ValueError("invalid category")
    for key, book in items.items():
        if not valid_id(key) or not isinstance(book, dict) or set(book) != {"title", "category_id"}:
            raise ValueError("invalid book")
        if not isinstance(book["title"], str) or not book["title"] or not valid_id(book["category_id"]) or book["category_id"] not in cats:
            raise ValueError("invalid book")

    fields = {
        "add_category": {"op", "id", "name"},
        "add_book": {"op", "id", "title", "category_id"},
        "rename_category": {"op", "id", "name"},
        "move_book": {"op", "id", "category_id"},
        "delete_book": {"op", "id"},
        "delete_category": {"op", "id"},
    }
    for operation in operations:
        if not isinstance(operation, dict) or operation.get("op") not in fields or set(operation) != fields[operation["op"]]:
            raise ValueError("invalid operation")
        op = operation["op"]
        ident = operation["id"]
        if not valid_id(ident):
            raise ValueError("invalid id")
        if "name" in operation and (not isinstance(operation["name"], str) or not operation["name"]):
            raise ValueError("invalid name")
        if "title" in operation and (not isinstance(operation["title"], str) or not operation["title"]):
            raise ValueError("invalid title")
        if "category_id" in operation and (not valid_id(operation["category_id"]) or operation["category_id"] not in cats):
            raise ValueError("unknown category")
        if op == "add_category":
            if ident in cats:
                raise ValueError("duplicate category")
            cats[ident] = operation["name"]
        elif op == "add_book":
            if ident in items:
                raise ValueError("duplicate book")
            items[ident] = {"title": operation["title"], "category_id": operation["category_id"]}
        elif op == "rename_category":
            if ident not in cats:
                raise ValueError("unknown category")
            cats[ident] = operation["name"]
        elif op == "move_book":
            if ident not in items:
                raise ValueError("unknown book")
            items[ident]["category_id"] = operation["category_id"]
        elif op == "delete_book":
            if ident not in items:
                raise ValueError("unknown book")
            del items[ident]
        else:
            if ident not in cats:
                raise ValueError("category cannot be deleted")
            del cats[ident]
    return {"categories": {k: deepcopy(cats[k]) for k in sorted(cats)}, "books": {k: deepcopy(items[k]) for k in sorted(items)}}

